function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // Seven
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 - 50);
  ctx.lineTo(W/2 + 50, H/2 - 50);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.lineTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 50, H/2 - 50);
  ctx.stroke();

  // Three
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2 + 40, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 80, H/2 + 80, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // Three
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2 + 40, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 30, H/2 + 80, 20, 0, 2 * Math.PI);
  ctx.stroke();

  // oscillation
  ctx.beginPath();
  ctx.arc(W/2, H/2 + Math.sin(t) * 20, 10, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
